from marshmallow import validate, ValidationError

validator = validate.Odd()

# Test positive odd numbers
for n in [1, 3, 5, 7, 9]:
    try:
        result = validator(n)
        print(f"✓ {n} is odd: {result}")
    except ValidationError as e:
        print(f"✗ {n} failed: {e}")

# Test negative odd numbers
for n in [-1, -3, -5, -7, -9]:
    try:
        result = validator(n)
        print(f"✓ {n} is odd: {result}")
    except ValidationError as e:
        print(f"✗ {n} failed: {e}")

# Test even numbers (should fail)
for n in [0, 2, 4, 6, -2, -4, -6]:
    try:
        result = validator(n)
        print(f"✗ {n} should have failed!")
    except ValidationError as e:
        print(f"✓ {n} correctly rejected: {e}")

# Test custom error message
custom_validator = validate.Odd(error="{input} is not odd!")
try:
    custom_validator(4)
except ValidationError as e:
    print(f"✓ Custom message works: {e}")
EOF

.venv/bin/python << 'EOF'
from marshmallow import validate, ValidationError

v = validate.Finite()

# Test valid input
print("Testing 0:", v(0))

# Test with 1e309 - should be rejected as it's infinity
try:
    result = v(1e309)
    print(f"1e309 = {result}")
except ValidationError as e:
    print(f"1e309 rejected: {e}")

# Test NaN
try:
    v(float('nan'))
except ValidationError as e:
    print(f"NaN rejected: {e}")

# Test positive infinity
try:
    v(float('inf'))
except ValidationError as e:
    print(f"inf rejected: {e}")

# Test negative infinity
try:
    v(float('-inf'))
except ValidationError as e:
    print(f"-inf rejected: {e}")

# Test custom error message
v_custom = validate.Finite(error="Value {input} is not finite")
try:
    v_custom(float('nan'))
except ValidationError as e:
    print(f"Custom error: {e}")
EOF
